// Deterministic ids for records generated by a recurring item: two devices
// generating the same occurrence offline produce the same id, so a later
// newest-wins merge folds them into one record.
//
// SHA-256 of `${recurringId}:${occurrenceDate}`, first 16 bytes, formatted as
// a UUID with version nibble 5 and the RFC 4122 variant bits.
export async function occurrenceRecordId(
  recurringId: string,
  occurrenceDate: string,
): Promise<string> {
  const digest = await crypto.subtle.digest(
    'SHA-256',
    new TextEncoder().encode(`${recurringId}:${occurrenceDate}`),
  )
  const b = new Uint8Array(digest).slice(0, 16)
  b[6] = (b[6] & 0x0f) | 0x50
  b[8] = (b[8] & 0x3f) | 0x80
  const hex = Array.from(b, (n) => n.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}
